from fractions import Fraction as F
from itertools import combinations, permutations
from pathlib import Path
import csv, hashlib, json, resource, time

resource.setrlimit(resource.RLIMIT_CPU, (30, 31))
resource.setrlimit(resource.RLIMIT_AS, (1024**3, 1024**3))
started = time.monotonic()
ROOT = Path('/workspace/poisson-p4')
N = 6
ZERO = (0,)*N

def term(a, *indices):
    m = [0]*N
    for i in indices: m[i] += 1
    return {tuple(m): F(a)} if a else {}

def add(*polys):
    out = {}
    for p in polys:
        for m,a in p.items(): out[m] = out.get(m,F(0))+a
    return {m:a for m,a in out.items() if a}

def scale(p,a): return {m:a*b for m,b in p.items() if a*b}

def mul(p,q):
    out = {}
    for m,a in p.items():
        for n,b in q.items():
            k = tuple(x+y for x,y in zip(m,n))
            out[k] = out.get(k,F(0))+a*b
    return {m:a for m,a in out.items() if a}

def der(p,i):
    out = {}
    for m,a in p.items():
        if m[i]:
            k = list(m); k[i] -= 1
            out[tuple(k)] = a*m[i]
    return out

def tensor(data):
    out = {}
    for (i,j),p in data.items(): out[i,j] = p; out[j,i] = scale(p,-1)
    return out

P = tensor({
 (1,2):term(1,0,1),
 (1,3):add(term(-1,0,4),term(-3,1,1),term(-1,2,2)),
 (1,4):term(-2,1,2),
 (2,3):add(term(-2,0,3),term(-2,1,2)),
 (2,4):add(term(-3,0,4),term(-1,1,1),term(-3,2,2)),
 (3,4):add(term(4,1,4),term(-4,2,3)),
})
R = tensor({
 (0,1):term(F(-1,2),0,1), (0,2):term(F(-3,2),0,2),
 (0,3):term(F(1,2),0,3), (0,4):term(F(3,2),2,2),
 (1,2):term(F(-1,2),1,2), (1,3):term(F(1,4),1,3),
 (2,3):term(1,2,3),
})
pairs = list(combinations(range(5),2))

def projective_jacobi(A):
    triple = {}
    for i,j,k in combinations(range(5),3):
        triple[i,j,k] = add(*(mul(A.get((a,l),{}),der(A.get((b,c),{}),l))
                       for a,b,c in [(i,j,k),(j,k,i),(k,i,j)] for l in range(5)))
    result = {}
    for inds in combinations(range(5),4):
        result[inds] = add(*(scale(mul(term(1,inds[k]),triple[inds[:k]+inds[k+1:]]),(-1)**k)
                             for k in range(4)))
    return result

def divisor(A):
    values = []
    for i in range(5):
        a,b,c,d = [j for j in range(5) if j != i]
        pf = add(mul(A.get((a,b),{}),A.get((c,d),{})),
                 scale(mul(A.get((a,c),{}),A.get((b,d),{})),-1),
                 mul(A.get((a,d),{}),A.get((b,c),{})))
        values.append(scale(mul(term(1,i),pf),(-1)**i))
    return add(*values)

Pt = tensor({ij:add(P.get(ij,{}),mul(term(1,5),R.get(ij,{}))) for ij in pairs})
jac = projective_jacobi(Pt)
assert all(not v for v in jac.values())
quad = add(term(1,5,1,3),term(4,0,4),term(4,1,1),term(4,2,2))
cubic = add(term(1,5,0,2,4),term(1,5,2,2,2),term(2,0,0,4),term(2,0,1,1),term(2,0,2,2))
expected = scale(mul(quad,cubic),F(-3,8))
assert divisor(Pt) == expected
assert divisor(P) == scale(mul(term(1,0),mul(add(term(1,0,4),term(1,1,1),term(1,2,2)),add(term(1,0,4),term(1,1,1),term(1,2,2)))), -3)

def weights(A,w):
    return {ij:{m:sum(m[k]*w[k] for k in range(5))-w[ij[0]]-w[ij[1]]
                   for m in A.get(ij,{})} for ij in pairs}

first_weights = (1,0,0,-3,-2)
P1 = tensor({ij:add(P.get(ij,{}),R.get(ij,{})) for ij in pairs})
ws = weights(P1,first_weights)
assert all(k >= 0 for values in ws.values() for k in values.values())
initial = tensor({ij:{m:a for m,a in P1.get(ij,{}).items() if ws[ij][m] == 0} for ij in pairs})
expected_initial = dict(R)
expected_initial.pop((0,4)); expected_initial.pop((4,0))
assert all(initial.get(ij,{}) == expected_initial.get(ij,{}) for ij in pairs)
assert divisor(initial) == term(F(-3,8),0,1,2,3,4)
assert all(not v for v in projective_jacobi(initial).values())
for ij in pairs:
    assert all(m == tuple(int(k in ij) for k in range(6)) for m in initial.get(ij,{}))

second_weights = (0,1,1,2,2)
assert set(k for values in weights(P,second_weights).values() for k in values.values()) == {-1}
assert set(k for values in weights(R,second_weights).values() for k in values.values()) == {0}

# The affine chart w=1 gives a nondegenerate four-dimensional logarithmic matrix.
Gamma = [[F(0) for j in range(4)] for i in range(4)]
for i,j in combinations(range(4),2):
    entry = initial.get((i,j),{})
    val = next(iter(entry.values()),F(0))
    Gamma[i][j] = val; Gamma[j][i] = -val
aug = [row[:] + [F(int(i==j)) for j in range(4)] for i,row in enumerate(Gamma)]
for j in range(4):
    pivot = next(i for i in range(j,4) if aug[i][j])
    aug[j],aug[pivot] = aug[pivot],aug[j]
    a = aug[j][j]; aug[j] = [v/a for v in aug[j]]
    for i in range(4):
        if i != j:
            a = aug[i][j]; aug[i] = [u-a*v for u,v in zip(aug[i],aug[j])]
inverse = [row[4:] for row in aug]
B = [[F(0) for j in range(5)] for i in range(5)]
for i,j in combinations(range(4),2): B[i][j] = F(3,2)*inverse[i][j]; B[j][i] = -B[i][j]
for i in range(4): B[i][4] = -sum(B[i]); B[4][i] = -B[i][4]
assert all(sum(row)==0 for row in B)
edges = []
for i,j in combinations(range(5),2):
    if not B[i][j]: continue
    vals = {k:(B[j][k]+B[k][i])/B[i][j] for k in range(5) if k not in (i,j)}
    if all(v.denominator==1 and v>=0 for v in vals.values()):
        assert sum(vals.values())==2
        edges.append({'edge':[i,j],'orders':{str(k):int(v) for k,v in vals.items()}})

def canon(edges, perm):
    return sorted((tuple(sorted(perm[i] for i in r['edge'])),
                   tuple(sorted((perm[int(k)],v) for k,v in r['orders'].items()))) for r in edges)
matches = []
with (ROOT/'legacy/v02/baseline/data/p4_toric_components_40.csv').open() as stream:
    for row in csv.DictReader(stream):
        target = canon(json.loads(row['edge_orders']),range(5))
        for perm in permutations(range(5)):
            if canon(edges,perm) == target:
                matches.append({'id':row['id'],'permutation':list(perm)}); break
assert len(matches)==1

def serialize(A): return {f'{i},{j}':[[list(m),str(a)] for m,a in sorted(A.get((i,j),{}).items())] for i,j in pairs}
inputs = ['reports/CLASSIFICATION_ANISOTROPIC_DOUBLE_QUADRIC_20261107.json',
          'legacy/v02/baseline/data/p4_toric_components_40.csv',
          'research/classification/BETA_ZERO_COVERAGE.md']
source = Path(__file__).read_text()
out = {'task_id':'A','field':'QQ','source_sha256':hashlib.sha256(source.encode()).hexdigest(),
       'independent_checker_source':source,'input_sha256':{p:hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in inputs},
       'method':'Pure Fraction sparse exterior-polynomial arithmetic; no SymPy or producer imported.',
       'P':serialize(P),'R':serialize(R),'all_parameter_projective_Jacobi_zero':True,
       'factored_divisor':'-3/8*(t*u*z+4*h*w+4*u^2+4*v^2)*(t*h*v*w+t*v^3+2*h^2*w+2*h*u^2+2*h*v^2)',
       'SNC_deformation_weights':list(first_weights),'SNC_initial':serialize(initial),
       'SNC_divisor_coefficient':'-3/8','all_SNC_weights_nonnegative':True,
       'contraction_weights':list(second_weights),'P_weight':-1,'R_weight':0,
       'biresidue_matrix':[[str(v) for v in row] for row in B],
       'SNC_smoothable_edges':edges,'SNC_maximal_diagram_match':matches[0],
       'component_scope':'Membership in the finite union of MPS40 follows from the SNC orbit limit. The maximal diagram match alone is not asserted to identify a unique component containing P or P+R.',
       'global_exhaustion_proved':False,'elapsed_seconds':time.monotonic()-started}
output = ROOT/'reports/CLASSIFICATION_ANISOTROPIC_MPS_DEFORMATION_REVIEW_20261107.json'
with output.open('x') as stream: json.dump(out,stream,indent=2);stream.write('\n')
print(json.dumps({k:out[k] for k in ['all_parameter_projective_Jacobi_zero','all_SNC_weights_nonnegative','SNC_maximal_diagram_match','elapsed_seconds']},indent=2))
